#include <iostream>
#include <string>
#include <vector>
using namespace std;

int main() {
    string expr;
    cin >> expr;

    // 解析数字和运算符
    vector<int> nums;
    vector<char> ops;
    int num = 0;
    for (int i = 0; i <= expr.size(); i++) {
        if (i == expr.size() || expr[i] == '+' || expr[i] == '-' ||
            expr[i] == '*' || expr[i] == '/') {
            nums.push_back(num);
            if (i < expr.size()) ops.push_back(expr[i]);
            num = 0;
        } else {
            num = num * 10 + (expr[i] - '0');
        }
    }

    // 先处理乘除
    vector<int> nums2;
    vector<char> ops2;
    nums2.push_back(nums[0]);
    for (int i = 0; i < ops.size(); i++) {
        if (ops[i] == '*') {
            nums2.back() *= nums[i+1];
        } else if (ops[i] == '/') {
            nums2.back() /= nums[i+1];
        } else {
            ops2.push_back(ops[i]);
            nums2.push_back(nums[i+1]);
        }
    }

    // 再处理加减
    int result = nums2[0];
    for (int i = 0; i < ops2.size(); i++) {
        if (ops2[i] == '+') result += nums2[i+1];
        else result -= nums2[i+1];
    }

    cout << result << endl;
    return 0;
}

